import functools, itertools
def lcs(a, b):
    @functools.lru_cache(None)
    def f(i, j):
        if i == len(a) or j == len(b): return 0
        return 1 + f(i + 1, j + 1) if a[i] == b[j] else max(f(i + 1, j), f(i, j + 1))
    return f(0, 0)
def inside(s, big):
    it = iter(big); return all(x in it for x in s)
def slow(a, b): return max(k for k in range(len(a) + 1) if any(inside(c, b) for c in itertools.combinations(a, k)))
A = (3, 1, 3, 2, 7, 4, 8, 2); B = (6, 5, 1, 2, 3, 4)
assert lcs(A, B) == slow(A, B)
result = lcs(A, B)

